package com.cenedu.backend.ai.problem.render; import com.cenedu.backend.domain.problem.authoring.diagram.*; public final class NumberLineSvgRenderer { public String render(NumberLineDiagramSpecV1 s){int p=s.viewport().padding(),y=s.viewport().height()/2;var b=new StringBuilder("<line x1=\"").append(p).append("\" y1=\"").append(y).append("\" x2=\"").append(s.viewport().width()-p).append("\" y2=\"").append(y).append("\" stroke=\"#000000\"/>");for(var point:s.points())b.append("<circle cx=\"").append(p+20).append("\" cy=\"").append(y).append("\" r=\"5\" fill=\"none\" stroke=\"#000000\"/>");return b.toString();} }
